<script setup lang="ts">
import { ref, watch } from 'vue'; import { Close, Delete } from '@element-plus/icons-vue'; import { ElMessage } from 'element-plus'; import { api } from '../api'; import type { Track, TrackComment } from '../types'; import { useAuthStore } from '../store/auth'
const props=defineProps<{open:boolean;track:Track|null}>(); const emit=defineEmits<{close:[]}>(); const auth=useAuthStore(); const items=ref<TrackComment[]>([]), text=ref(''), loading=ref(false), sending=ref(false)
async function load(){if(!props.track||!props.open)return;loading.value=true;try{items.value=(await api.comments(props.track.id)).items}finally{loading.value=false}}
async function submit(){if(!props.track||!text.value.trim())return; if(text.value.trim().length>1000){ElMessage.warning('评论最多 1000 字');return}sending.value=true;try{items.value.unshift(await api.addComment(props.track.id,text.value.trim()));text.value='';ElMessage.success('评论已发布')}finally{sending.value=false}}
async function remove(c:TrackComment){if(!props.track)return;await api.deleteComment(props.track.id,c.id);items.value=items.value.filter(x=>x.id!==c.id);ElMessage.success('评论已删除')}
watch(()=>[props.open,props.track?.id],load,{immediate:true})
</script>
<template><aside v-if="props.open" class="player-drawer comment-panel" aria-label="评论"><header><div><span class="eyebrow">COMMENTS</span><h3>评论</h3></div><button class="icon-button" aria-label="关闭评论" @click="emit('close')"><Close/></button></header><div class="comment-list" v-loading="loading"><div v-if="!items.length&&!loading" class="drawer-empty">还没有评论，来留下第一句话吧。</div><article v-for="c in items" :key="String(c.id)" class="comment-item"><div class="comment-avatar">{{c.username.slice(0,1)}}</div><div><strong>{{c.username}}</strong><time>{{new Date(c.createdAt).toLocaleString()}}</time><p>{{c.content}}</p></div><button v-if="c.canDelete||c.userId===auth.user?.id" class="icon-button danger" aria-label="删除评论" @click="remove(c)"><Delete/></button></article></div><form v-if="auth.user&&props.track" class="comment-form" @submit.prevent="submit"><textarea v-model="text" maxlength="1000" placeholder="写下你的评论…" aria-label="评论内容"></textarea><div><small>{{text.length}}/1000</small><button class="dark-button" :disabled="sending||!text.trim()">发布评论</button></div></form><p v-else class="login-hint">登录后可以发表评论</p></aside></template>
